/*
 * kvarn_test: kvarn page codec through the FastRPC runtime
 * (kvarn_commit / kvarn_decode), k4v2 and k4v4.
 *
 * The oracle is the Rust reference codec: `kvarn_case.h` is generated by
 * `cargo run -p myelin-pack --example kvarn_dump` and carries the rotated
 * page, the encoded reference page, its scales and the reference decode of
 * four tokens.  The DSP encoder uses the DSP libm, so the scale comparison is
 * reported per field and the code comparison has a 99.5 % gate (the sim stand
 * dsp/hvx/kvarn_main.c checks bit-exactness on the same page).
 *
 * Run on device: ./kvarn_test
 * Exit code: 0 pass, 2 numerics, 10.. RPC failure.
 */
#include "lfmgemv.h"
#include "kvarn_case.h"
#include "kvarn_impl.h"

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "rpcmem.h"

static const int g_tokens[4] = { 0, 1, 17, KV_CASE_TOKENS - 1 };

static int enable_unsigned(void)
{
    struct remote_rpc_control_unsigned_module um;
    um.domain = CDSP_DOMAIN_ID;
    um.enable = 1;
    return remote_session_control(DSPRPC_CONTROL_UNSIGNED_MODULE, &um,
                                  (uint32_t)sizeof(um));
}

static int count_eq(const unsigned char *a, const unsigned char *b, int bytes)
{
    int i, n = 0;
    for (i = 0; i < bytes; i++)
        n += (a[i] == b[i]);
    return n;
}

static int close_enough(float a, float b)
{
    float scale = fabsf(a) > 1.0f ? fabsf(a) : 1.0f;
    return fabsf(a - b) <= 1e-6f * scale;
}

static int run_format(int v_bits, const unsigned char *ref_page,
                      const float *dec_k, const float *dec_v)
{
    int page_bytes = (int)kvarn_page_bytes(v_bits);
    unsigned char *page = (unsigned char *)malloc((size_t)page_bytes);
    unsigned char rot[KV_CASE_TOKENS * KV_CASE_DIM * 2];
    float out[KVARN_DIM];
    int times[8] = { 0 };
    int rc, i, t, bad_k = 0, bad_v = 0, kcode_eq, vcode_eq, scale_eq;
    int kcode_len = KVARN_KCODE_BYTES;
    int vcode_len = KV_CASE_TOKENS * KV_CASE_DIM * v_bits / 8;
    int scale_len = page_bytes - kcode_len - vcode_len;

    if (!page)
        return 3;
    memcpy(rot, kv_case_rotated, sizeof(rot));
    rc = lfmgemv_kvarn_commit(v_bits, rot, (int)sizeof(rot), page, page_bytes,
                              times, 8);
    if (rc != 0) {
        printf("kvarn_commit k4v%d rc=%d\n", v_bits, rc);
        free(page);
        return 10 + (rc & 7);
    }
    kcode_eq = count_eq(page, ref_page, kcode_len);
    vcode_eq = count_eq(page + kcode_len, ref_page + kcode_len, vcode_len);
    scale_eq = count_eq(page + kcode_len + vcode_len,
                        ref_page + kcode_len + vcode_len, scale_len);

    printf("KVARN k4v%d commit: K codes %4d/%4d V codes %4d/%4d scales %3d/%3d"
           "  dsp=%d us  %s\n",
           v_bits, kcode_eq, kcode_len, vcode_eq, vcode_len, scale_eq, scale_len,
           times[0],
           (kcode_eq * 1000 >= kcode_len * 995 &&
            vcode_eq * 1000 >= vcode_len * 995) ? "OK" : "FAIL");
    if (!(kcode_eq * 1000 >= kcode_len * 995 &&
          vcode_eq * 1000 >= vcode_len * 995)) {
        free(page);
        return 2;
    }

    for (t = 0; t < 4; t++) {
        rc = lfmgemv_kvarn_decode(v_bits, page, page_bytes, g_tokens[t], 0,
                                  (unsigned char *)out, (int)sizeof(out), times, 8);
        if (rc != 0) {
            printf("kvarn_decode k rc=%d\n", rc);
            free(page);
            return 10 + (rc & 7);
        }
        for (i = 0; i < KVARN_DIM; i++)
            if (!close_enough(out[i], dec_k[t * KVARN_DIM + i]))
                bad_k++;
        rc = lfmgemv_kvarn_decode(v_bits, page, page_bytes, g_tokens[t], 1,
                                  (unsigned char *)out, (int)sizeof(out), times, 8);
        if (rc != 0) {
            printf("kvarn_decode v rc=%d\n", rc);
            free(page);
            return 10 + (rc & 7);
        }
        for (i = 0; i < KVARN_DIM; i++)
            if (!close_enough(out[i], dec_v[t * KVARN_DIM + i]))
                bad_v++;
    }
    printf("KVARN k4v%d decode: K bad=%d V bad=%d  %s\n", v_bits, bad_k, bad_v,
           (bad_k == 0 && bad_v == 0) ? "OK" : "FAIL");
    free(page);
    return (bad_k == 0 && bad_v == 0) ? 0 : 2;
}

int main(void)
{
    int rc;

    setvbuf(stdout, NULL, _IONBF, 0);
    if ((rc = enable_unsigned()) != 0)
        printf("unsigned PD rc=%d (continuing)\n", rc);

    printf("KVARN stand: %dx%d page, k4v2 %d B, k4v4 %d B\n", KV_CASE_TOKENS,
           KV_CASE_DIM, KVARN_K4V2_BYTES, KVARN_K4V4_BYTES);

    rc = run_format(2, kv_case_k4v2_encoded, kv_case_k4v2_decoded_k,
                    kv_case_k4v2_decoded_v);
    if (rc != 0) {
        printf("KVARN RESULT: FAIL\n");
        return rc;
    }
    rc = run_format(4, kv_case_k4v4_encoded, kv_case_k4v4_decoded_k,
                    kv_case_k4v4_decoded_v);
    if (rc != 0) {
        printf("KVARN RESULT: FAIL\n");
        return rc;
    }
    printf("KVARN RESULT: PASS\n");
    return 0;
}
